// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 value, uint256 extra, address actor) public {
        vm.assume(extra <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        value = bound(value, 1, 1 ether);
        extra = bound(extra, 1, 2 ether);

        // make actor the owner
        vm.deal(actor, value + extra);
        vm.prank(actor);
        (bool okPay, ) = address(c).call{value: extra}("");
        assertTrue(okPay);

        // caller (test contract) must be owner for withdraw; owner is whoever deployed (this test contract)
        vm.deal(address(this), value);
        vm.deal(address(c), extra + value); // ensure balance covers value and exceeds it
        address(c).call{value: 0}(""); // no-op, fallback counts as deposit

        uint256 before = address(c).balance;
        vm.assume(before > value);

        c.withdraw(value);

        assertEq(address(c).balance, before - value);
    }

    receive() external payable {}
}
